package org.sleepwell.app;
import android.graphics.*;import android.graphics.pdf.PdfDocument;import com.google.zxing.*;import com.google.zxing.common.BitMatrix;import com.google.zxing.qrcode.QRCodeWriter;import com.google.zxing.qrcode.decoder.ErrorCorrectionLevel;import java.io.*;import java.security.SecureRandom;import java.util.*;
/** Original random printable payload. Only its existing MorningCode digest is returned to enrollment. */
final class GeneratedMorningQr {
 static final String PREFIX="SleepWell morning code v1:";
 static String create(){byte[] random=new byte[32];new SecureRandom().nextBytes(random);try{return PREFIX+Base64.getUrlEncoder().withoutPadding().encodeToString(random);}finally{Arrays.fill(random,(byte)0);}}
 static String validate(String payload){if(payload==null||!payload.matches("SleepWell morning code v1:[A-Za-z0-9_-]{43}"))throw new IllegalArgumentException("This unfinished generated code is unavailable. Generate a new one.");byte[] bytes=Base64.getUrlDecoder().decode(payload.substring(PREFIX.length()));if(bytes.length!=32||!createEncoding(bytes).equals(payload.substring(PREFIX.length())))throw new IllegalArgumentException("Invalid generated code");Arrays.fill(bytes,(byte)0);return payload;}
 private static String createEncoding(byte[] bytes){return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);}
 static final class Document{final String label,hash;final Bitmap preview;final byte[] png,pdf;Document(String label,String hash,Bitmap preview,byte[] png,byte[] pdf){this.label=label;this.hash=hash;this.preview=preview;this.png=png;this.pdf=pdf;}}
 static Document render(String payload,String rawLabel)throws Exception{validate(payload);String label=MorningCode.label(rawLabel);BitMatrix code=new QRCodeWriter().encode(payload,BarcodeFormat.QR_CODE,832,832,Map.of(EncodeHintType.ERROR_CORRECTION,ErrorCorrectionLevel.M,EncodeHintType.MARGIN,4,EncodeHintType.CHARACTER_SET,"UTF-8"));Bitmap bitmap=Bitmap.createBitmap(1024,1280,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);canvas.drawColor(Color.WHITE);Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);paint.setColor(Color.BLACK);paint.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));paint.setTextAlign(Paint.Align.CENTER);paint.setTextSize(38);canvas.drawText("SleepWell morning code",512,78,paint);paint.setTextSize(30);drawLabel(canvas,paint,label);int[] pixels=new int[832*832];for(int y=0;y<832;y++)for(int x=0;x<832;x++)pixels[y*832+x]=code.get(x,y)?Color.BLACK:Color.WHITE;Bitmap qr=Bitmap.createBitmap(pixels,832,832,Bitmap.Config.ARGB_8888);Arrays.fill(pixels,0);canvas.drawBitmap(qr,96,232,null);qr.recycle();paint.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));paint.setTextSize(24);canvas.drawText("Place this code away from your bed.",512,1124,paint);canvas.drawText("Anyone with a copy can use it for this challenge.",512,1164,paint);paint.setTextSize(20);canvas.drawText("Generated locally · no link or web service",512,1216,paint);ByteArrayOutputStream png=new ByteArrayOutputStream();if(!bitmap.compress(Bitmap.CompressFormat.PNG,100,new Limited(png,2*1024*1024)))throw new IOException("PNG could not be encoded");ByteArrayOutputStream pdf=new ByteArrayOutputStream();PdfDocument document=new PdfDocument();try{PdfDocument.Page page=document.startPage(new PdfDocument.PageInfo.Builder(595,842,1).create());page.getCanvas().drawColor(Color.WHITE);Paint image=new Paint(Paint.ANTI_ALIAS_FLAG|Paint.FILTER_BITMAP_FLAG);page.getCanvas().drawBitmap(bitmap,null,new RectF(40,80,555,724),image);document.finishPage(page);document.writeTo(new Limited(pdf,3*1024*1024));}finally{document.close();}return new Document(label,MorningCode.digest(payload),bitmap,png.toByteArray(),pdf.toByteArray());}
 static byte[] printPdf(android.content.Context app,Bitmap bitmap,android.print.PrintAttributes attributes)throws IOException{ByteArrayOutputStream output=new ByteArrayOutputStream();android.print.pdf.PrintedPdfDocument document=new android.print.pdf.PrintedPdfDocument(app,attributes);try{PdfDocument.Page page=document.startPage(0);Rect bounds=document.getPageContentRect();float scale=Math.min(bounds.width()/(float)bitmap.getWidth(),bounds.height()/(float)bitmap.getHeight());float width=bitmap.getWidth()*scale,height=bitmap.getHeight()*scale,left=bounds.left+(bounds.width()-width)/2,top=bounds.top+(bounds.height()-height)/2;page.getCanvas().drawColor(Color.WHITE);page.getCanvas().drawBitmap(bitmap,null,new RectF(left,top,left+width,top+height),new Paint(Paint.ANTI_ALIAS_FLAG|Paint.FILTER_BITMAP_FLAG));document.finishPage(page);document.writeTo(new Limited(output,3*1024*1024));return output.toByteArray();}finally{document.close();}}
 private static void drawLabel(Canvas canvas,Paint paint,String label){float width=880;int count=paint.breakText(label,true,width,null);if(count==label.length()){canvas.drawText(label,512,150,paint);return;}canvas.drawText(label.substring(0,count),512,142,paint);String rest=label.substring(count).stripLeading();while(paint.measureText(rest)>width&&paint.getTextSize()>18)paint.setTextSize(paint.getTextSize()-1);canvas.drawText(rest,512,185,paint);}
 private static final class Limited extends FilterOutputStream{final int max;int count;Limited(OutputStream output,int max){super(output);this.max=max;}public void write(int value)throws IOException{if(count>=max)throw new IOException("Printable code document exceeds its size limit");out.write(value);count++;}public void write(byte[] bytes,int at,int length)throws IOException{if(length>max-count)throw new IOException("Printable code document exceeds its size limit");out.write(bytes,at,length);count+=length;}}
 private GeneratedMorningQr(){}
}
